package com.example.grafanapocket;

import android.app.*;import android.appwidget.AppWidgetManager;import android.content.Intent;import android.graphics.*;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.*;

public class WidgetRefreshActivity extends Activity {
    int widgetId;Connection connection;WebView web;TextView status;boolean captured;
    @Override public void onCreate(Bundle b){super.onCreate(b);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);android.content.SharedPreferences p=getSharedPreferences("widgets",MODE_PRIVATE);connection=new SecureStore(this).get(p.getString("connection_"+widgetId,""));LinearLayout root=Ui.column(this);status=Ui.title(this,"正在生成小组件快照，请稍候…");status.setTextSize(15);Ui.fill(root,status);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,(int)(280*getResources().getDisplayMetrics().density)));setContentView(root);web.post(this::applyWidgetRatio);if(connection==null){status.setText("连接不存在");return;}new Thread(()->{try{GrafanaApi.ensureLogin(connection);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}}).start();}
    void applyWidgetRatio(){android.os.Bundle options=AppWidgetManager.getInstance(this).getAppWidgetOptions(widgetId);int width=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,180),height=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,100);float ratio=Math.max(0.35f,Math.min(1.25f,height/(float)Math.max(1,width)));ViewGroup.LayoutParams lp=web.getLayoutParams();lp.height=Math.max(1,Math.round(web.getWidth()*ratio));web.setLayoutParams(lp);web.postDelayed(()->web.evaluateJavascript("window.dispatchEvent(new Event('resize'))",null),300);}
    void load(){WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_ALWAYS_ALLOW);s.setUserAgentString(s.getUserAgentString()+" GrafanaPocketWidget/1.3");web.setWebViewClient(new WebViewClient(){@Override public void onReceivedHttpAuthRequest(WebView v,HttpAuthHandler h,String host,String realm){if("basic".equals(connection.auth))h.proceed(connection.user,connection.secret);else h.cancel();}@Override public void onPageFinished(WebView v,String url){status.setText("面板已加载，正在等待数据…");v.postDelayed(()->capture(),5000);}});android.content.SharedPreferences p=getSharedPreferences("widgets",MODE_PRIVATE);String path=p.getString("path_"+widgetId,connection.dashboard),panel=p.getString("panel_"+widgetId,"");String[] q=path.split("\\?",2);String base=q[0];if(!panel.isEmpty()&&base.startsWith("/d/"))base="/d-solo/"+base.substring(3);String query=(q.length>1?q[1]+"&":"")+"from="+p.getString("from_"+widgetId,"now-6h")+"&to="+p.getString("to_"+widgetId,"now")+"&kiosk"+(!panel.isEmpty()?"&panelId="+panel:"");path=base+"?"+query;String target=connection.url+(path.startsWith("/")?path:"/"+path);Map<String,String> headers=new HashMap<>();if("token".equals(connection.auth))headers.put("Authorization","Bearer "+connection.secret);web.loadUrl(target,headers);}
    void capture(){if(captured||web.getWidth()==0||web.getHeight()==0)return;captured=true;Bitmap bitmap=Bitmap.createBitmap(web.getWidth(),web.getHeight(),Bitmap.Config.ARGB_8888);int[] location=new int[2];web.getLocationInWindow(location);Rect area=new Rect(location[0],location[1],location[0]+web.getWidth(),location[1]+web.getHeight());PixelCopy.request(getWindow(),area,bitmap,result->{if(result==PixelCopy.SUCCESS)complete(bitmap);else{Canvas canvas=new Canvas(bitmap);web.draw(canvas);complete(bitmap);}},new Handler(Looper.getMainLooper()));}
    void complete(Bitmap bitmap){try{WidgetCache.save(this,widgetId,bitmap);GrafanaWidgetProvider.showCached(this,AppWidgetManager.getInstance(this),widgetId,"刚刚更新");Toast.makeText(this,"小组件已更新",Toast.LENGTH_SHORT).show();Intent home=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(home);finishAndRemoveTask();}catch(Exception e){captured=false;status.setText("生成快照失败："+e.getMessage());}}
    @Override protected void onDestroy(){if(web!=null)web.destroy();super.onDestroy();}
}
